ALTER TABLE public.evaluations ADD COLUMN reference_id uuid REFERENCES public.evaluation_prices(id);
UPDATE public.evaluations e SET reference_id=p.id FROM public.evaluation_prices p WHERE e.store_id=p.store_id AND lower(e.model)=lower(p.model) AND e.storage=p.storage AND e.reference_value IS NOT NULL;
CREATE OR REPLACE FUNCTION public.link_evaluation_reference() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND NEW.reference_value IS NOT NULL THEN SELECT id INTO NEW.reference_id FROM public.evaluation_prices WHERE store_id=NEW.store_id AND NOT archived AND lower(model)=lower(NEW.model) AND storage=NEW.storage; END IF; RETURN NEW; END $$;
CREATE TRIGGER link_evaluation_reference BEFORE INSERT ON public.evaluations FOR EACH ROW EXECUTE FUNCTION public.link_evaluation_reference();
CREATE OR REPLACE FUNCTION public.preserve_evaluation_reference() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.evaluations WHERE reference_id=OLD.id OR (store_id=OLD.store_id AND lower(model)=lower(OLD.model) AND storage=OLD.storage AND reference_value IS NOT NULL)) THEN UPDATE public.evaluation_prices SET archived=true WHERE id=OLD.id; RETURN NULL; END IF; RETURN OLD; END $$;
CREATE TRIGGER preserve_evaluation_reference BEFORE DELETE ON public.evaluation_prices FOR EACH ROW EXECUTE FUNCTION public.preserve_evaluation_reference();